insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As medidas de proteção requeridas por vítimas ou testemunhas de crimes que estejam coagidas ou expostas a grave ameaça em razão de colaborarem com a investigação ou processo criminal serão prestadas pela União, pelos Estados e pelo Distrito Federal, no âmbito de suas competências, na forma de programas especiais. A União, os Estados e o Distrito Federal poderão celebrar convênios e parcerias entre si ou com entidades não governamentais. A supervisão dos convênios de interesse da União fica a cargo do órgão do Ministério da Justiça responsável pela política de direitos humanos.', '["Proteção a vítimas e testemunhas coagidas ou ameaçadas por colaborarem.","Prestada pela União, Estados e DF por programas especiais.","Convênios e parcerias com entidades não governamentais.","Fiscalização federal pelo órgão de direitos humanos do Ministério da Justiça."]'::jsonb, '["A proteção é para quem COLABORA com a investigação ou o processo."]'::jsonb, 'A testemunha ameaçada por depor entra em programa de proteção estadual.', '["Assertiva que restringe a proteção às testemunhas, excluindo as vítimas, erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A proteção levará em conta a gravidade da coação ou ameaça à integridade física ou psicológica, a dificuldade de preveni-las ou reprimi-las pelos meios convencionais e a importância da pessoa para a produção da prova. Poderá ser estendida ao cônjuge ou companheiro, ascendentes, descendentes e dependentes que tenham convivência habitual com a vítima ou testemunha. Ficam excluídos os indivíduos cuja personalidade ou conduta seja incompatível com as restrições do programa, os condenados que cumprem pena e os indiciados ou acusados sob prisão cautelar, sem prejuízo de medidas de preservação da integridade física pelos órgãos de segurança. O ingresso exige a anuência do protegido ou de seu representante, que fica obrigado a cumprir as normas do programa. As medidas são mantidas em sigilo.', '["Critérios: gravidade da ameaça, dificuldade de prevenção e importância para a prova.","Extensão a cônjuge, companheiro, ascendentes, descendentes e dependentes.","Excluídos: condutas incompatíveis, condenados cumprindo pena e presos cautelares.","Anuência do protegido.","Sigilo das medidas."]'::jsonb, '["Voluntariedade: o ingresso depende da anuência do protegido.","Quem está preso cautelarmente é excluído do programa, mas a segurança policial continua."]'::jsonb, 'A família da testemunha que vive com ela pode ser incluída na proteção.', '["Assertiva que permite a inclusão sem a anuência do protegido erra: a anuência é sempre necessária."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Toda admissão no programa ou exclusão dele será precedida de consulta ao Ministério Público sobre o disposto no art. 2º e deverá ser subsequentemente comunicada à autoridade policial ou ao juiz competente.', '["Consulta prévia ao Ministério Público.","Comunicação posterior à autoridade policial ou ao juiz."]'::jsonb, '["A consulta ao MP é PRÉVIA; a comunicação à polícia ou ao juiz é POSTERIOR."]'::jsonb, 'Antes de excluir um protegido, o programa consulta o Ministério Público.', '["Assertiva que dispensa a consulta ao Ministério Público erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cada programa será dirigido por um conselho deliberativo, com representantes do Ministério Público, do Poder Judiciário e de órgãos públicos e privados relacionados com a segurança pública e a defesa dos direitos humanos. A execução das atividades ficará a cargo de um dos órgãos representados no conselho, com agentes de formação e capacitação compatíveis. Os órgãos policiais prestarão a colaboração e o apoio necessários.', '["Conselho deliberativo dirige o programa.","Composição: Ministério Público, Judiciário e órgãos de segurança e direitos humanos.","Execução por um dos órgãos do conselho.","Apoio dos órgãos policiais."]'::jsonb, '["O conselho decide; a execução é de um dos órgãos representados."]'::jsonb, 'O conselho é composto por representantes do MP, do Judiciário e de órgãos públicos.', '["Assertiva que atribui a direção do programa à polícia erra: é do conselho deliberativo."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A solicitação de ingresso no programa poderá ser encaminhada ao órgão executor pelo interessado; por representante do Ministério Público; pela autoridade policial que conduz a investigação; pelo juiz competente para a instrução do processo; ou por órgãos e entidades de defesa dos direitos humanos. A solicitação será instruída com a qualificação da pessoa, sua vida pregressa, o fato delituoso e a coação ou ameaça. O órgão executor poderá solicitar, com a aquiescência do interessado, documentos e exames técnicos. Em caso de urgência, a vítima ou testemunha poderá ficar provisoriamente sob custódia policial até a decisão do conselho.', '["Legitimados: interessado, MP, delegado, juiz e entidades de direitos humanos.","Instrução com qualificação, vida pregressa, fato e ameaça.","Documentos e exames com a aquiescência do interessado.","Urgência: custódia policial provisória."]'::jsonb, '["Rol de legitimados inclui o próprio interessado.","Custódia provisória até a decisão do conselho."]'::jsonb, 'O delegado que conduz o inquérito solicita o ingresso da testemunha no programa.', '["Assertiva que impede o próprio interessado de solicitar o ingresso erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O conselho deliberativo decidirá sobre o ingresso do protegido no programa ou a sua exclusão e sobre as providências necessárias ao cumprimento do programa. As deliberações serão tomadas por maioria absoluta de seus membros, e sua execução ficará sujeita à disponibilidade orçamentária.', '["Decide ingresso, exclusão e providências.","Maioria absoluta dos membros.","Execução sujeita à disponibilidade orçamentária."]'::jsonb, '["Maioria ABSOLUTA, e não simples."]'::jsonb, 'A admissão de uma testemunha exige maioria absoluta do conselho.', '["Assertiva que exige unanimidade do conselho erra: basta maioria absoluta."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os programas compreendem, entre outras, as medidas aplicáveis isolada ou cumulativamente, conforme a gravidade e as circunstâncias: segurança na residência, incluindo controle de telecomunicações; escolta nos deslocamentos; transferência de residência ou acomodação provisória; preservação da identidade, imagem e dados pessoais; ajuda financeira mensal para subsistência; suspensão temporária das atividades funcionais, sem prejuízo dos vencimentos, para servidor público ou militar; apoio e assistência social, médica e psicológica; sigilo dos atos praticados; e apoio para o cumprimento de obrigações civis e administrativas que exijam o comparecimento pessoal. A ajuda financeira mensal terá um teto fixado pelo conselho no início de cada exercício financeiro.', '["Rol exemplificativo de medidas, isoladas ou cumuladas.","Segurança, escolta, transferência, preservação da identidade.","Ajuda financeira mensal com teto fixado pelo conselho.","Suspensão das atividades funcionais sem prejuízo dos vencimentos.","Apoio social, médico e psicológico."]'::jsonb, '["Rol EXEMPLIFICATIVO (''dentre outras'').","O teto da ajuda é fixado no início de cada exercício financeiro."]'::jsonb, 'A testemunha é transferida de cidade e recebe ajuda financeira mensal.', '["Assertiva que considera taxativo o rol de medidas erra: é exemplificativo."]'::jsonb, '[]'::jsonb, '["Art. 8º","Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando entender necessário, o conselho deliberativo poderá solicitar ao Ministério Público que requeira ao juiz a concessão de medidas cautelares direta ou indiretamente relacionadas com a eficácia da proteção.', '["Conselho solicita ao MP; o MP requer ao juiz.","Medidas cautelares ligadas à eficácia da proteção."]'::jsonb, '["O conselho não pede diretamente ao juiz; passa pelo Ministério Público."]'::jsonb, 'O conselho pede ao MP que requeira medida cautelar para reforçar a proteção.', '["Assertiva que permite ao conselho requerer diretamente ao juiz as cautelares erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em casos excepcionais, considerando a gravidade da coação ou ameaça, o conselho poderá encaminhar o requerimento da pessoa protegida ao juiz competente para registros públicos, objetivando a alteração de nome completo. A alteração poderá estender-se às pessoas do §1º do art. 2º, inclusive aos filhos menores, com providências para resguardar direitos de terceiros. O requerimento será fundamentado, com oitiva prévia do Ministério Público, rito sumaríssimo e segredo de justiça. Concedida a alteração, a sentença determina a averbação no registro original da menção da alteração, sem o nome novo, o fornecimento dos documentos e a remessa ao órgão nacional do registro único de identificação civil. O conselho mantém controle sigiloso da localização do protegido. Cessada a coação, o protegido pode solicitar o retorno ao nome original.', '["Alteração de nome completo em casos excepcionais.","Extensão a cônjuge, familiares e filhos menores.","Rito sumaríssimo e segredo de justiça, com oitiva do MP.","Averbação sem o novo nome no registro original.","Retorno ao nome original quando cessar a ameaça."]'::jsonb, '["Medida EXCEPCIONAL.","O novo nome não consta da averbação."]'::jsonb, 'A testemunha de crime de facção altera o nome, e o registro original mostra apenas a menção à alteração.', '["Assertiva que torna pública a alteração de nome da testemunha erra: o procedimento é sigiloso."]'::jsonb, '[{"termo":"Rito sumaríssimo","significado":"Procedimento simplificado e rápido."}]'::jsonb, '["Lei de Registros Públicos"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A exclusão da pessoa protegida do programa poderá ocorrer a qualquer tempo, por solicitação do próprio interessado ou por decisão do conselho deliberativo, em consequência da cessação dos motivos que ensejaram a proteção ou da conduta incompatível do protegido.', '["Exclusão a qualquer tempo.","Pedido do interessado ou decisão do conselho.","Causas: cessação dos motivos ou conduta incompatível."]'::jsonb, '["A saída do programa é voluntária."]'::jsonb, 'O protegido que quebra as regras do programa pode ser excluído pelo conselho.', '["Assertiva que impede o protegido de pedir sua exclusão erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-10'
