insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O indiciado ou acusado que colaborar voluntariamente com a investigação policial e o processo criminal na identificação dos demais coautores ou partícipes, na localização da vítima com vida e na recuperação total ou parcial do produto do crime, no caso de condenação, terá pena reduzida de um a dois terços.', '["Colaboração voluntária na investigação e no processo.","Em caso de condenação, redução da pena de um a dois terços."]'::jsonb, '["Aqui a vítima deve ser localizada COM VIDA.","Redução de um a dois terços (não é perdão)."]'::jsonb, 'O réu que ajuda a localizar a vítima com vida e os cúmplices tem a pena reduzida.', '["Assertiva que exige a primariedade do colaborador no art. 14 erra: ela é do perdão judicial."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-14'
