insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão aplicadas em benefício do colaborador, na prisão ou fora dela, medidas especiais de segurança e proteção a sua integridade física, considerando ameaça ou coação eventual ou efetiva. Se estiver sob prisão temporária, preventiva ou em flagrante, será custodiado em dependência separada dos demais presos. Durante a instrução criminal, o juiz poderá determinar em seu favor as medidas do art. 8º. No regime fechado, o juiz poderá determinar medidas especiais para a segurança do colaborador em relação aos demais apenados.', '["Medidas especiais de segurança para o colaborador, preso ou solto.","Custódia em dependência separada.","Medidas cautelares do art. 8º durante a instrução.","Segurança no regime fechado."]'::jsonb, '["Colaborador preso cautelarmente fica separado dos demais presos."]'::jsonb, 'O colaborador preso em flagrante é mantido em cela separada.', '["Assertiva que mantém o colaborador junto com os demais presos erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-15'
