insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 18 da Lei de Registros Públicos passa a determinar que, ressalvado o disposto nos arts. 45, 57, §7º, e 95, parágrafo único, a certidão será lavrada independentemente de despacho judicial, devendo mencionar o livro de registro ou o documento arquivado no cartório.', '["Certidão independe de despacho judicial.","Ressalvados os casos de sigilo (arts. 45, 57, §7º, e 95)."]'::jsonb, '["Altera a Lei de Registros Públicos; as ressalvas protegem o sigilo."]'::jsonb, 'O cartório emite a certidão sem ordem do juiz, salvo nos casos ressalvados.', '["Assertiva que exige despacho judicial em toda certidão erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
