select u.id, u.content_sha256, 'As despesas decorrentes da aplicação desta Lei, pela União, correrão à conta de dotação consignada no orçamento.', '["Despesas da União pagas por dotação orçamentária."]'::jsonb, '["A execução das deliberações depende de disponibilidade orçamentária."]'::jsonb, 'Os gastos do programa federal saem do orçamento da União.', '["Assertiva que cria fonte própria de custeio fora do orçamento erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
