select u.id, u.content_sha256, 'Esta Lei entra em vigor na data de sua publicação, produzindo efeitos desde então.', '["Vigência imediata."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'A lei passou a valer na data da publicação.', '["Assertiva que prevê vacatio legis erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
