insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O repasse de recursos do Fundo Nacional de Segurança Pública e do Fundo Penitenciário Nacional para ações que envolvam o uso da força pelos órgãos de segurança pública dos Estados, do Distrito Federal e dos Municípios está condicionado à observância do disposto no Decreto.', '["Repasses do Fundo Nacional de Segurança Pública e do Fundo Penitenciário Nacional.","Condicionados à observância do Decreto."]'::jsonb, '["Mecanismo de indução: sem cumprir o Decreto, não há repasse."]'::jsonb, 'O Estado que ignora as regras do Decreto pode perder repasses federais.', '["Assertiva que dispensa a observância do Decreto para receber repasses erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
