insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estão sujeitos a controle e fiscalização, em todas as etapas (fabricação, armazenamento, compra, venda, posse, transporte, importação, exportação, utilização, entre outras), todos os produtos químicos que possam ser utilizados como insumo na elaboração de substâncias entorpecentes, psicotrópicas ou que determinem dependência física ou psíquica. O controle aplica-se também a essas substâncias quando não estiverem sob controle do Ministério da Saúde. Considera-se produto químico a substância química e as formulações que a contenham, nas concentrações estabelecidas em portaria, em qualquer estado físico, independentemente do nome fantasia e do uso lícito a que se destina.', '["Controle de todos os produtos químicos usados como insumo de drogas.","Abrange todas as etapas, da fabricação à utilização.","Aplica-se a substâncias sem controle do Ministério da Saúde.","Conceito de produto químico por concentração em portaria."]'::jsonb, '["O controle vale mesmo para uso LÍCITO e independe do nome fantasia."]'::jsonb, 'Um solvente usado na indústria também se sujeita ao controle se puder servir de insumo para drogas.', '["Assertiva que dispensa o controle quando o produto tem uso lícito erra."]'::jsonb, '[{"termo":"Insumo","significado":"Produto usado como matéria-prima na fabricação de outro."}]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
