insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para exercer qualquer atividade sujeita a controle e fiscalização, a pessoa física ou jurídica deverá se cadastrar e requerer licença de funcionamento ao Departamento de Polícia Federal, nos termos da portaria do art. 2º, independentemente de outras exigências legais. As pessoas jurídicas já cadastradas providenciarão o recadastramento. Quem exercer a atividade de modo eventual deverá se cadastrar e requerer autorização especial para suas operações.', '["Cadastro e licença de funcionamento na PF.","Recadastramento das já cadastradas.","Atividade eventual: cadastro e autorização especial."]'::jsonb, '["Licença para atividade REGULAR; autorização especial para atividade EVENTUAL."]'::jsonb, 'A empresa que revende solventes controlados exige licença de funcionamento da PF.', '["Assertiva que dispensa o cadastro de quem exerce a atividade apenas eventualmente erra: exige autorização especial."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
