insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constitui infração administrativa: deixar de cadastrar-se ou licenciar-se no prazo legal; deixar de comunicar à PF, em trinta dias, qualquer alteração cadastral ou estatutária, bem como a suspensão ou mudança de atividade; omitir informações ou prestá-las incompletas ou inexatas; não apresentar documentos de controle quando solicitado; exercer a atividade sem licença ou autorização especial; exercer a atividade com pessoa não autorizada ou irregular; deixar de informar suspeita de desvio; importar, exportar ou reexportar sem autorização prévia; alterar a composição de produto controlado sem comunicação; adulterar laudos, notas fiscais, rótulos e embalagens; deixar de informar a concentração do produto na embalagem ou rótulo; deixar de comunicar à PF furto, roubo ou extravio em quarenta e oito horas; e dificultar a ação do órgão de controle.', '["Treze hipóteses de infração administrativa.","Falta de cadastro ou licença.","Omissão ou inexatidão de informações.","Adulteração de laudos, notas e rótulos.","Furto, roubo ou extravio: comunicar em quarenta e oito horas.","Dificultar a fiscalização."]'::jsonb, '["Prazos distintos: trinta dias (alteração), vinte e quatro horas (suspeita de desvio, art. 11) e quarenta e oito horas (furto, roubo ou extravio)."]'::jsonb, 'Empresa que perde um lote e não avisa a PF em quarenta e oito horas comete infração administrativa.', '["Assertiva que fixa em vinte e quatro horas o prazo para comunicar furto ou extravio erra: são quarenta e oito horas."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
