insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O descumprimento das normas da Lei, independentemente de responsabilidade penal, sujeitará os infratores, cumulativa ou isoladamente, a advertência formal; apreensão do produto químico em situação irregular; suspensão ou cancelamento de licença de funcionamento; revogação da autorização especial; e multa de R$ 2.128,20 a R$ 1.064.100,00. Na dosimetria consideram-se a situação econômica, a conduta, a reincidência, a natureza da infração, a quantidade dos produtos e as circunstâncias. A multa poderá ser paga em até cinco parcelas mensais. Cabe recurso ao Diretor-Geral da Polícia Federal.', '["Medidas: advertência, apreensão, suspensão ou cancelamento de licença, revogação de autorização especial e multa.","Aplicadas cumulativa ou isoladamente.","Multa de R$ 2.128,20 a R$ 1.064.100,00.","Parcelamento da multa em até cinco parcelas.","Recurso ao Diretor-Geral da PF."]'::jsonb, '["As medidas administrativas independem de responsabilidade penal."]'::jsonb, 'Empresa reincidente na omissão de informações recebe multa e suspensão da licença.', '["Assertiva que condiciona as medidas à condenação penal erra: elas independem da esfera penal."]'::jsonb, '[]'::jsonb, '["Art. 12"]'::jsonb, 'under_review', 'claude'
