select u.id, u.content_sha256, 'São isentos da taxa, sem prejuízo das demais obrigações da Lei, os órgãos da Administração Pública direta federal, estadual e municipal; as instituições públicas de ensino, pesquisa e saúde; e as entidades particulares de caráter assistencial, filantrópico e sem fins lucrativos que comprovem essa condição na forma da lei.', '["Isenção para órgãos da Administração direta.","Isenção para instituições públicas de ensino, pesquisa e saúde.","Isenção para entidades assistenciais e filantrópicas comprovadas."]'::jsonb, '["A isenção é da TAXA; as demais obrigações permanecem."]'::jsonb, 'A universidade pública não paga a taxa, mas continua obrigada a se licenciar.', '["Assertiva que dispensa as isentas das obrigações de controle erra: a isenção é só da taxa."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
