insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei dispõe sobre a investigação criminal conduzida pelo delegado de polícia, regulamentando suas atribuições e prerrogativas.', '["Trata da investigação criminal conduzida pelo delegado de polícia."]'::jsonb, '["Lei federal geral, que vale para delegados da Polícia Federal e das Polícias Civis."]'::jsonb, 'O delegado conduz o inquérito policial conforme esta Lei.', '["Assertiva que restringe a Lei aos delegados federais erra: trata do delegado de polícia em geral."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'delegado' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia são de natureza jurídica, essenciais e exclusivas de Estado. Ao delegado, como autoridade policial, cabe a condução da investigação criminal por inquérito policial ou outro procedimento previsto em lei, para apurar circunstâncias, materialidade e autoria. Cabe-lhe requisitar perícia, informações, documentos e dados. O inquérito em curso só poderá ser avocado ou redistribuído por superior hierárquico mediante despacho fundamentado, por interesse público ou por inobservância de procedimentos que prejudique a investigação. A remoção do delegado dá-se somente por ato fundamentado. O indiciamento, privativo do delegado, dá-se por ato fundamentado, mediante análise técnico-jurídica do fato, indicando autoria, materialidade e circunstâncias.', '["Função jurídica, essencial e exclusiva de Estado.","Condução da investigação criminal pelo delegado.","Requisição de perícia, informações, documentos e dados.","Avocação ou redistribuição só por despacho fundamentado.","Remoção por ato fundamentado.","Indiciamento privativo do delegado, fundamentado."]'::jsonb, '["O §3º foi vetado.","INDICIAMENTO é privativo do delegado e deve ser fundamentado.","Remoção sem fundamentação viola a Lei."]'::jsonb, 'O delegado indicia o investigado por ato fundamentado, apontando autoria e materialidade.', '["Assertiva que permite ao Ministério Público indiciar o investigado erra: o indiciamento é privativo do delegado."]'::jsonb, '[{"termo":"Indiciamento","significado":"Ato do delegado que aponta alguém como provável autor do crime."}]'::jsonb, '["Código de Processo Penal (inquérito)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'delegado' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O cargo de delegado de polícia é privativo de bacharel em Direito, devendo-lhe ser dispensado o mesmo tratamento protocolar que recebem os magistrados, os membros da Defensoria Pública e do Ministério Público e os advogados.', '["Cargo privativo de bacharel em Direito.","Tratamento protocolar igual ao de magistrados, defensores, promotores e advogados."]'::jsonb, '["Exige formação em Direito."]'::jsonb, 'Só quem é bacharel em Direito pode ocupar o cargo de delegado.', '["Assertiva que permite o cargo a qualquer bacharel de nível superior erra: é privativo de bacharel em Direito."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
